const input = $('Schedule Trigger').first()?.json ?? {};
const tickAt = input.tick_at ?? input.timestamp ?? new Date().toISOString();
const tick = new Date(tickAt);
tick.setUTCSeconds(0, 0);
tick.setUTCMinutes(Math.floor(tick.getUTCMinutes() / 10) * 10);
const tickKey = tick.toISOString();
return [{ json: { envelope: {
  request_id: 'req-dispatch-' + tickKey,
  operation_id: 'op-dispatch-tick-' + tickKey.replace(/[^0-9A-Z]/gi, ''),
  event_type: 'SCHEDULED_JOB',
  actor_user_id: 'SYSTEM',
  branch_id: null,
  business_date: null,
  config_version: null,
  payload: { intent: 'READ_STATUS', tick_at: tickAt }
} } }];

const K = new Uint32Array([
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
]);

const rotr = (value, bits) => (value >>> bits) | (value << (32 - bits));

/** Dependency-free SHA-256 for Node tests and n8n Code nodes. */
function sha256(input) {
  const bytes = new TextEncoder().encode(String(input));
  const bitLength = bytes.length * 8;
  const paddedLength = Math.ceil((bytes.length + 9) / 64) * 64;
  const padded = new Uint8Array(paddedLength);
  padded.set(bytes);
  padded[bytes.length] = 0x80;
  const view = new DataView(padded.buffer);
  view.setUint32(paddedLength - 8, Math.floor(bitLength / 0x100000000));
  view.setUint32(paddedLength - 4, bitLength >>> 0);

  let h0 = 0x6a09e667;
  let h1 = 0xbb67ae85;
  let h2 = 0x3c6ef372;
  let h3 = 0xa54ff53a;
  let h4 = 0x510e527f;
  let h5 = 0x9b05688c;
  let h6 = 0x1f83d9ab;
  let h7 = 0x5be0cd19;

  const schedule = new Uint32Array(64);
  for (let offset = 0; offset < paddedLength; offset += 64) {
    for (let i = 0; i < 16; i += 1) schedule[i] = view.getUint32(offset + i * 4);
    for (let i = 16; i < 64; i += 1) {
      const s0 = rotr(schedule[i - 15], 7) ^ rotr(schedule[i - 15], 18) ^ (schedule[i - 15] >>> 3);
      const s1 = rotr(schedule[i - 2], 17) ^ rotr(schedule[i - 2], 19) ^ (schedule[i - 2] >>> 10);
      schedule[i] = (schedule[i - 16] + s0 + schedule[i - 7] + s1) >>> 0;
    }

    let a = h0;
    let b = h1;
    let c = h2;
    let d = h3;
    let e = h4;
    let f = h5;
    let g = h6;
    let h = h7;
    for (let i = 0; i < 64; i += 1) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const choice = (e & f) ^ (~e & g);
      const temp1 = (h + S1 + choice + K[i] + schedule[i]) >>> 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const majority = (a & b) ^ (a & c) ^ (b & c);
      const temp2 = (S0 + majority) >>> 0;
      h = g;
      g = f;
      f = e;
      e = (d + temp1) >>> 0;
      d = c;
      c = b;
      b = a;
      a = (temp1 + temp2) >>> 0;
    }
    h0 = (h0 + a) >>> 0;
    h1 = (h1 + b) >>> 0;
    h2 = (h2 + c) >>> 0;
    h3 = (h3 + d) >>> 0;
    h4 = (h4 + e) >>> 0;
    h5 = (h5 + f) >>> 0;
    h6 = (h6 + g) >>> 0;
    h7 = (h7 + h) >>> 0;
  }

  return [h0, h1, h2, h3, h4, h5, h6, h7]
    .map((value) => value.toString(16).padStart(8, '0'))
    .join('');
}

const ACTIVE_VALUES = new Set(['ACTIVE', 'ENABLED', 'YES', 'TRUE', '1']);
const INACTIVE_VALUES = new Set(['INACTIVE', 'DISABLED', 'NO', 'FALSE', '0']);
const DAY_NAMES = new Map([
  ['MON', 1],
  ['MONDAY', 1],
  ['TUE', 2],
  ['TUESDAY', 2],
  ['WED', 3],
  ['WEDNESDAY', 3],
  ['THU', 4],
  ['THURSDAY', 4],
  ['FRI', 5],
  ['FRIDAY', 5],
  ['SAT', 6],
  ['SATURDAY', 6],
  ['SUN', 7],
  ['SUNDAY', 7],
]);

const scheduleText = (value) => (value == null ? '' : String(value).trim());

function field(row, names) {
  for (const name of names) {
    if (row?.[name] !== undefined && row?.[name] !== null && scheduleText(row[name]) !== '') return row[name];
  }
  return '';
}

function required(row, names, label) {
  const value = scheduleText(field(row, names));
  if (!value) throw new Error(`DISPATCH_CONFIG_REQUIRED:${label}`);
  return value;
}

function parseStatus(value, label) {
  const normalized = scheduleText(value).toUpperCase();
  if (!normalized) throw new Error(`DISPATCH_CONFIG_REQUIRED:${label}`);
  if (ACTIVE_VALUES.has(normalized)) return true;
  if (INACTIVE_VALUES.has(normalized)) return false;
  throw new Error(`DISPATCH_CONFIG_STATUS_INVALID:${label}`);
}

function parseInteger(value, label, { minimum = 0 } = {}) {
  const normalized = scheduleText(value);
  if (!/^-?\d+$/.test(normalized)) throw new Error(`DISPATCH_CONFIG_INTEGER_INVALID:${label}`);
  const parsed = Number(normalized);
  if (!Number.isSafeInteger(parsed) || parsed < minimum) throw new Error(`DISPATCH_CONFIG_INTEGER_INVALID:${label}`);
  return parsed;
}

function parseTime(value) {
  const normalized = scheduleText(value);
  const match = /^(?<hour>[01]\d|2[0-3]):(?<minute>[0-5]\d)$/.exec(normalized);
  if (!match) throw new Error('DISPATCH_CONFIG_TIME_INVALID:local_time');
  return {
    local_time: normalized,
    hour: Number(match.groups.hour),
    minute: Number(match.groups.minute),
  };
}

function parseDays(value) {
  const normalized = scheduleText(value).toUpperCase();
  if (!normalized || normalized === '*') return [1, 2, 3, 4, 5, 6, 7];
  const values = normalized.split(/[\s,|]+/).filter(Boolean).flatMap((token) => {
    if (/^[1-7]$/.test(token)) return [Number(token)];
    const day = DAY_NAMES.get(token);
    if (day) return [day];
    const vietnameseDay = /^T([2-7])$/.exec(token);
    return vietnameseDay ? [Number(vietnameseDay[1]) - 1] : [];
  });
  const unique = [...new Set(values)].sort((left, right) => left - right);
  if (unique.length === 0 || unique.length !== normalized.split(/[\s,|]+/).filter(Boolean).length) {
    throw new Error('DISPATCH_CONFIG_DAYS_INVALID:days_of_week');
  }
  return unique;
}

function validateTimezone(timezone) {
  try {
    new Intl.DateTimeFormat('en-US', { timeZone: timezone }).format(new Date(0));
  } catch {
    throw new Error(`DISPATCH_CONFIG_TIMEZONE_INVALID:${timezone}`);
  }
  return timezone;
}

function activeBranch(branchRows, branchId) {
  if (!Array.isArray(branchRows) || branchRows.length === 0) return null;
  const row = branchRows.find((candidate) => scheduleText(candidate?.branch_id) === branchId);
  if (!row) throw new Error(`DISPATCH_BRANCH_NOT_FOUND:${branchId}`);
  return row;
}

function parseScheduleRow(row, { branchRows = [], defaultTimezone = '' } = {}) {
  if (!row || typeof row !== 'object') throw new TypeError('DISPATCH_CONFIG_ROW_INVALID');

  const scheduleId = required(row, ['schedule_id', 'lich_id', 'schedule_code'], 'schedule_id');
  const jobCode = required(row, ['job_code', 'job_id', 'task_code'], 'job_code');
  const workerWorkflow = required(row, ['worker_workflow', 'workflow_name', 'target_workflow'], 'worker_workflow');
  const branchId = required(row, ['branch_id', 'branch_code'], 'branch_id');
  const branch = activeBranch(branchRows, branchId);
  const statusValue = field(row, ['trang_thai', 'status', 'enabled']);
  const scheduleEnabled = parseStatus(statusValue, 'trang_thai');
  const branchEnabled = branch ? parseStatus(field(branch, ['trang_thai', 'status']), 'CONFIG_BRANCH.trang_thai') : true;
  const timezone = validateTimezone(required({ timezone: field(row, ['timezone', 'time_zone']) || field(branch, ['timezone']) || defaultTimezone }, ['timezone'], 'timezone'));
  const parsedTime = parseTime(required(row, ['local_time', 'run_time', 'gio_chay'], 'local_time'));
  const days = parseDays(field(row, ['days_of_week', 'weekday', 'thu_trong_tuan']));
  const graceMinutes = parseInteger(field(row, ['grace_minutes', 'grace_window_minutes', 'phut_catchup']), 'grace_minutes');
  const maxAttempts = parseInteger(field(row, ['max_attempts', 'retry_limit', 'max_retries']), 'max_attempts', { minimum: 1 });

  return Object.freeze({
    schedule_id: scheduleId,
    job_code: jobCode,
    worker_workflow: workerWorkflow,
    branch_id: branchId,
    timezone,
    days_of_week: Object.freeze(days),
    local_time: parsedTime.local_time,
    hour: parsedTime.hour,
    minute: parsedTime.minute,
    grace_minutes: graceMinutes,
    max_attempts: maxAttempts,
    schedule_enabled: scheduleEnabled,
    branch_enabled: branchEnabled,
    enabled: scheduleEnabled && branchEnabled,
    trang_thai: scheduleEnabled ? 'ACTIVE' : 'INACTIVE',
  });
}

function parseScheduleRows({ rows = [], branchRows = [], defaultTimezone = '' } = {}) {
  if (!Array.isArray(rows)) throw new TypeError('DISPATCH_CONFIG_ROWS_INVALID');
  return rows.map((row) => parseScheduleRow(row, { branchRows, defaultTimezone }));
}


const heartbeatText = (value) => (value == null ? '' : String(value).trim());
const FAILED_STATUSES = new Set(['FAILED', 'ERROR']);

function parseHeartbeatInstant(value) {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) throw new Error('DISPATCH_TIME_INVALID:tickAt');
  return date;
}

function heartbeatIdentity(tickAt) {
  const date = parseHeartbeatInstant(tickAt);
  date.setUTCSeconds(0, 0);
  date.setUTCMinutes(Math.floor(date.getUTCMinutes() / 10) * 10);
  const tickKey = date.toISOString();
  const heartbeatKey = `heartbeat:${tickKey}`;
  return {
    tick_key: tickKey,
    dispatch_key: heartbeatKey,
    operation_id: `op-heartbeat-${sha256(heartbeatKey).slice(0, 32)}`,
  };
}

function orderedHeartbeatRows(rows) {
  return [...(Array.isArray(rows) ? rows : [])]
    .filter((row) => heartbeatText(row?.record_type).toUpperCase() === 'HEARTBEAT' || heartbeatText(row?.dispatch_key).startsWith('heartbeat:'))
    .sort((left, right) => heartbeatText(left.updated_at || left.created_at).localeCompare(heartbeatText(right.updated_at || right.created_at)));
}

function trailingFailures(rows) {
  let failures = 0;
  for (const row of [...rows].reverse()) {
    if (!FAILED_STATUSES.has(heartbeatText(row.status).toUpperCase())) break;
    failures += 1;
  }
  return failures;
}

function historyId(identity) {
  return `dispatch-history-${sha256(`${identity.dispatch_key}|heartbeat`).slice(0, 24)}`;
}

function decideHeartbeat({ heartbeatRows = [], tickAt, success, failureThreshold } = {}) {
  const threshold = Number(failureThreshold);
  if (!Number.isSafeInteger(threshold) || threshold < 1) throw new Error('DISPATCH_HEARTBEAT_THRESHOLD_INVALID');
  if (typeof success !== 'boolean') throw new TypeError('DISPATCH_HEARTBEAT_RESULT_REQUIRED');

  const identity = heartbeatIdentity(tickAt);
  const rows = orderedHeartbeatRows(heartbeatRows);
  const duplicate = rows.find((row) => heartbeatText(row.dispatch_key) === identity.dispatch_key);
  if (duplicate) {
    return {
      action: 'SKIP',
      reason: 'HEARTBEAT_ALREADY_RECORDED',
      ...identity,
      status: heartbeatText(duplicate.status).toUpperCase(),
      consecutive_failures: Number(heartbeatText(duplicate.failure_count)) || 0,
      critical_alert: false,
      recovery_alert: false,
      alert_state: heartbeatText(duplicate.alert_state).toUpperCase() || 'HEALTHY',
      history_row: duplicate,
    };
  }

  const priorFailures = trailingFailures(rows);
  const previous = rows.at(-1);
  const previousWasCritical = heartbeatText(previous?.alert_state).toUpperCase() === 'CRITICAL' || priorFailures >= threshold;
  const consecutiveFailures = success ? 0 : priorFailures + 1;
  const criticalAlert = !success && consecutiveFailures >= threshold && priorFailures < threshold;
  const recoveryAlert = success && previousWasCritical;
  const alertState = success ? 'HEALTHY' : consecutiveFailures >= threshold ? 'CRITICAL' : 'DEGRADED';
  const status = success ? 'SUCCEEDED' : 'FAILED';
  const now = parseHeartbeatInstant(tickAt).toISOString();
  const historyRow = {
    history_id: historyId(identity),
    record_type: 'HEARTBEAT',
    dispatch_key: identity.dispatch_key,
    operation_id: identity.operation_id,
    schedule_id: '',
    job_code: 'DISPATCH_HEARTBEAT',
    worker_workflow: 'WF04_V2_DISPATCHER',
    branch_id: '*',
    occurrence_date: now.slice(0, 10),
    scheduled_at_local: '',
    status,
    attempt_number: '1',
    retryable: success ? '' : 'YES',
    failure_count: String(consecutiveFailures),
    error_code: success ? '' : 'DISPATCH_TICK_FAILED',
    error_id: '',
    heartbeat_failure_count: String(consecutiveFailures),
    alert_state: alertState,
    critical_alert: criticalAlert ? 'YES' : '',
    recovery_alert: recoveryAlert ? 'YES' : '',
    created_at: now,
    updated_at: now,
  };

  return {
    action: 'RECORD',
    reason: success ? (recoveryAlert ? 'RECOVERY' : 'HEALTHY') : criticalAlert ? 'CRITICAL_THRESHOLD_REACHED' : 'FAILURE',
    ...identity,
    status,
    consecutive_failures: consecutiveFailures,
    critical_alert: criticalAlert,
    recovery_alert: recoveryAlert,
    alert_state: alertState,
    history_row: historyRow,
  };
}


const WEEKDAY_NUMBERS = new Map([
  ['Mon', 1],
  ['Tue', 2],
  ['Wed', 3],
  ['Thu', 4],
  ['Fri', 5],
  ['Sat', 6],
  ['Sun', 7],
]);

const COMPLETED_STATUSES = new Set(['SUCCESS', 'SUCCEEDED', 'COMMITTED', 'COMPLETED', 'DONE']);
const IN_FLIGHT_STATUSES = new Set(['CLAIMED', 'RUNNING', 'DISPATCHED', 'PREPARED']);
const FAILURE_STATUSES = new Set(['FAILED', 'RETRYING']);
const WARNING_STATUSES = new Set(['WARNING', 'WARNED']);

const dispatchText = (value) => (value == null ? '' : String(value).trim());

function parseDispatchInstant(value, label) {
  const date = value instanceof Date ? new Date(value.getTime()) : new Date(value);
  if (Number.isNaN(date.getTime())) throw new Error(`DISPATCH_TIME_INVALID:${label}`);
  return date;
}

function pad(value) {
  return String(value).padStart(2, '0');
}

function localParts(date, timezone) {
  const formatter = new Intl.DateTimeFormat('en-US', {
    timeZone: timezone,
    weekday: 'short',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hourCycle: 'h23',
  });
  const parts = Object.fromEntries(formatter.formatToParts(date)
    .filter((part) => part.type !== 'literal')
    .map((part) => [part.type, part.value]));
  const weekday = WEEKDAY_NUMBERS.get(parts.weekday);
  if (!weekday) throw new Error(`DISPATCH_TIMEZONE_WEEKDAY_INVALID:${timezone}`);
  return {
    year: Number(parts.year),
    month: Number(parts.month),
    day: Number(parts.day),
    hour: Number(parts.hour),
    minute: Number(parts.minute),
    weekday,
    local_date: `${parts.year}-${parts.month}-${parts.day}`,
    local_time: `${parts.hour}:${parts.minute}`,
  };
}

function datePartsFromWallDate(wallDate) {
  const date = new Date(wallDate);
  const dayOfWeek = date.getUTCDay() === 0 ? 7 : date.getUTCDay();
  return {
    year: date.getUTCFullYear(),
    month: date.getUTCMonth() + 1,
    day: date.getUTCDate(),
    weekday: dayOfWeek,
  };
}

function wallDateFor(local, dayOffset = 0) {
  return Date.UTC(local.year, local.month - 1, local.day) - dayOffset * 24 * 60 * 60 * 1000;
}

function wallMinutes(year, month, day, hour, minute) {
  return Date.UTC(year, month - 1, day, hour, minute) / 60000;
}

function occurrenceFor(local, schedule, dateParts, differenceMinutes) {
  const localDate = `${dateParts.year}-${pad(dateParts.month)}-${pad(dateParts.day)}`;
  const localTime = schedule.local_time;
  return {
    local_date: localDate,
    local_time: localTime,
    scheduled_at_local: `${localDate}T${localTime}:00`,
    timezone: schedule.timezone,
    weekday: dateParts.weekday,
    lateness_minutes: Math.max(0, differenceMinutes),
  };
}

function findOccurrence(local, schedule) {
  const currentWallDate = wallDateFor(local);
  const currentDayScheduled = schedule.days_of_week.includes(local.weekday);
  if (currentDayScheduled) {
    const difference = wallMinutes(local.year, local.month, local.day, local.hour, local.minute)
      - wallMinutes(local.year, local.month, local.day, schedule.hour, schedule.minute);
    if (difference < 0) {
      return occurrenceFor(local, schedule, {
        year: local.year,
        month: local.month,
        day: local.day,
        weekday: local.weekday,
      }, difference);
    }
  }

  for (let offset = 0; offset <= 7; offset += 1) {
    const candidateDate = currentWallDate - offset * 24 * 60 * 60 * 1000;
    const dateParts = datePartsFromWallDate(candidateDate);
    if (!schedule.days_of_week.includes(dateParts.weekday)) continue;
    const scheduledWall = wallMinutes(dateParts.year, dateParts.month, dateParts.day, schedule.hour, schedule.minute);
    const nowWall = wallMinutes(local.year, local.month, local.day, local.hour, local.minute);
    const difference = nowWall - scheduledWall;
    if (difference >= 0) return occurrenceFor(local, schedule, dateParts, difference);
  }

  for (let offset = 1; offset <= 7; offset += 1) {
    const candidateDate = currentWallDate + offset * 24 * 60 * 60 * 1000;
    const dateParts = datePartsFromWallDate(candidateDate);
    if (schedule.days_of_week.includes(dateParts.weekday)) return occurrenceFor(local, schedule, dateParts, -1);
  }

  throw new Error(`DISPATCH_OCCURRENCE_NOT_FOUND:${schedule.schedule_id}`);
}

function evaluateSchedule({ schedule, now } = {}) {
  if (!schedule || typeof schedule !== 'object') throw new TypeError('DISPATCH_SCHEDULE_REQUIRED');
  if (!schedule.enabled) return { phase: 'DISABLED', occurrence: null, lateness_minutes: null };
  const instant = parseDispatchInstant(now, 'now');
  const local = localParts(instant, schedule.timezone);
  const occurrence = findOccurrence(local, schedule);
  const nowWall = wallMinutes(local.year, local.month, local.day, local.hour, local.minute);
  const scheduledParts = occurrence.scheduled_at_local.slice(0, 16).split(/[T:-]/).map(Number);
  const scheduledWall = wallMinutes(scheduledParts[0], scheduledParts[1], scheduledParts[2], scheduledParts[3], scheduledParts[4]);
  const difference = nowWall - scheduledWall;
  const phase = difference < 0
    ? 'NOT_DUE'
    : difference === 0
      ? 'DUE'
      : difference <= schedule.grace_minutes
        ? 'CATCH_UP'
        : 'OUTSIDE_WINDOW';
  return {
    phase,
    occurrence: { ...occurrence, lateness_minutes: Math.max(0, difference) },
    lateness_minutes: Math.max(0, difference),
  };
}

function dispatchIdentity({ schedule, occurrence } = {}) {
  if (!schedule?.schedule_id || !schedule?.branch_id || !occurrence?.local_date || !occurrence?.local_time) {
    throw new Error('DISPATCH_IDENTITY_INPUT_INVALID');
  }
  const dispatch_key = `dispatch:${schedule.schedule_id}:${schedule.branch_id}:${occurrence.local_date}:${occurrence.local_time}`;
  return {
    dispatch_key,
    operation_id: `op-dispatch-${sha256(dispatch_key).slice(0, 32)}`,
  };
}

function parseAttempt(row) {
  const parsed = Number(dispatchText(row?.attempt_number));
  return Number.isSafeInteger(parsed) && parsed >= 0 ? parsed : 0;
}

function isYes(value) {
  return ['YES', 'TRUE', '1', 'Y'].includes(dispatchText(value).toUpperCase());
}

function sortHistory(rows) {
  return [...rows].sort((left, right) => {
    const leftTime = dispatchText(left.updated_at || left.created_at);
    const rightTime = dispatchText(right.updated_at || right.created_at);
    return leftTime.localeCompare(rightTime) || parseAttempt(left) - parseAttempt(right);
  });
}

function historyForKey(historyRows, dispatchKey) {
  return sortHistory((Array.isArray(historyRows) ? historyRows : [])
    .filter((row) => dispatchText(row?.dispatch_key) === dispatchKey && dispatchText(row?.record_type).toUpperCase() !== 'HEARTBEAT'));
}

function rowId(identity, status, attempt) {
  return `dispatch-history-${sha256(`${identity.dispatch_key}|${status}|${attempt}`).slice(0, 24)}`;
}

function historyRow({ identity, schedule, occurrence, status, attempt, now, retryable = '', errorCode = '' }) {
  return {
    history_id: rowId(identity, status, attempt),
    record_type: 'JOB',
    dispatch_key: identity.dispatch_key,
    operation_id: identity.operation_id,
    schedule_id: schedule.schedule_id,
    job_code: schedule.job_code,
    worker_workflow: schedule.worker_workflow,
    branch_id: schedule.branch_id,
    occurrence_date: occurrence.local_date,
    scheduled_at_local: occurrence.scheduled_at_local,
    status,
    attempt_number: String(attempt),
    retryable,
    failure_count: '',
    error_code: errorCode,
    error_id: '',
    heartbeat_failure_count: '',
    alert_state: '',
    critical_alert: '',
    recovery_alert: '',
    created_at: now,
    updated_at: now,
  };
}

function workerEnvelope({ identity, schedule, occurrence, requestId, configVersion, attempt }) {
  const request = dispatchText(requestId);
  const version = dispatchText(configVersion);
  if (!request) throw new Error('DISPATCH_REQUEST_ID_REQUIRED');
  if (!version) throw new Error('DISPATCH_CONFIG_VERSION_REQUIRED');
  return {
    request_id: request,
    operation_id: identity.operation_id,
    event_type: 'SCHEDULED_JOB',
    branch_id: schedule.branch_id,
    actor_user_id: 'SYSTEM',
    business_date: occurrence.local_date,
    config_version: version,
    payload: {
      dispatch_key: identity.dispatch_key,
      schedule_id: schedule.schedule_id,
      job_code: schedule.job_code,
      worker_workflow: schedule.worker_workflow,
      timezone: schedule.timezone,
      scheduled_at_local: occurrence.scheduled_at_local,
      attempt_number: attempt,
    },
  };
}

function skipResult({ phase, reason, occurrence, identity }) {
  return {
    action: 'SKIP',
    reason,
    phase,
    occurrence,
    ...(identity ? identity : {}),
  };
}

function decideDispatch({
  schedule,
  now,
  historyRows = [],
  requestId,
  configVersion,
} = {}) {
  if (!schedule || typeof schedule !== 'object') throw new TypeError('DISPATCH_SCHEDULE_REQUIRED');
  const nowInstant = parseDispatchInstant(now, 'now').toISOString();
  if (!schedule.enabled) return { action: 'SKIP', reason: schedule.schedule_enabled ? 'BRANCH_INACTIVE' : 'DISABLED', phase: 'DISABLED' };

  const evaluated = evaluateSchedule({ schedule, now: nowInstant });
  const identity = dispatchIdentity({ schedule, occurrence: evaluated.occurrence });
  if (evaluated.phase === 'NOT_DUE') return skipResult({ ...evaluated, identity, reason: 'NOT_DUE' });

  const matchingHistory = historyForKey(historyRows, identity.dispatch_key);
  if (matchingHistory.some((row) => COMPLETED_STATUSES.has(dispatchText(row.status).toUpperCase()))) {
    return skipResult({ ...evaluated, identity, reason: 'ALREADY_COMPLETED' });
  }
  if (matchingHistory.some((row) => IN_FLIGHT_STATUSES.has(dispatchText(row.status).toUpperCase()))) {
    return skipResult({ ...evaluated, identity, reason: 'ALREADY_IN_FLIGHT' });
  }
  if (evaluated.phase === 'OUTSIDE_WINDOW') {
    if (matchingHistory.some((row) => WARNING_STATUSES.has(dispatchText(row.status).toUpperCase()))) {
      return skipResult({ ...evaluated, identity, reason: 'WARNING_ALREADY_RECORDED' });
    }
    return {
      action: 'WARN',
      reason: 'OUTSIDE_WINDOW',
      phase: evaluated.phase,
      occurrence: evaluated.occurrence,
      ...identity,
      warning: {
        code: 'DISPATCH_OUTSIDE_WINDOW',
        message_safe: `Scheduled job ${schedule.job_code} is outside its grace window`,
        lateness_minutes: evaluated.lateness_minutes,
      },
      history_row: historyRow({
        identity,
        schedule,
        occurrence: evaluated.occurrence,
        status: 'WARNING',
        attempt: 0,
        now: nowInstant,
        errorCode: 'DISPATCH_OUTSIDE_WINDOW',
      }),
    };
  }

  const latestFailure = [...matchingHistory].reverse().find((row) => FAILURE_STATUSES.has(dispatchText(row.status).toUpperCase()));
  const attempt = latestFailure ? parseAttempt(latestFailure) + 1 : 1;
  if (latestFailure && !isYes(latestFailure.retryable)) {
    return skipResult({ ...evaluated, identity, reason: 'FAILURE_NOT_RETRYABLE' });
  }
  if (latestFailure && attempt > schedule.max_attempts) {
    return skipResult({ ...evaluated, identity, reason: 'RETRY_LIMIT_REACHED' });
  }

  const action = latestFailure ? 'RETRY' : 'DISPATCH';
  const reason = latestFailure ? 'RETRY_FAILED' : evaluated.phase === 'CATCH_UP' ? 'GRACE_CATCH_UP' : 'DUE';
  return {
    action,
    reason,
    phase: evaluated.phase,
    occurrence: evaluated.occurrence,
    ...identity,
    attempt_number: attempt,
    envelope: workerEnvelope({ identity, schedule, occurrence: evaluated.occurrence, requestId, configVersion, attempt }),
    history_row: historyRow({
      identity,
      schedule,
      occurrence: evaluated.occurrence,
      status: 'CLAIMED',
      attempt,
      now: nowInstant,
      retryable: latestFailure ? 'YES' : '',
    }),
  };
}

function buildDispatchPlan({
  scheduleRows = [],
  branchRows = [],
  historyRows = [],
  heartbeatRows = [],
  defaultTimezone = '',
  now,
  requestId,
  configVersion,
  heartbeatSuccess,
  heartbeatFailureThreshold,
} = {}) {
  const schedules = parseScheduleRows({ rows: scheduleRows, branchRows, defaultTimezone });
  const decisions = schedules.map((schedule) => decideDispatch({
    schedule,
    now,
    historyRows,
    requestId,
    configVersion,
  }));
  const heartbeat = decideHeartbeat({
    heartbeatRows,
    tickAt: now,
    success: heartbeatSuccess,
    failureThreshold: heartbeatFailureThreshold,
  });
  const dispatches = decisions.filter((decision) => ['DISPATCH', 'RETRY'].includes(decision.action));
  const warnings = decisions.filter((decision) => decision.action === 'WARN').map((decision) => decision.warning);
  if (heartbeat.critical_alert) warnings.push({ code: 'DISPATCH_HEARTBEAT_CRITICAL', consecutive_failures: heartbeat.consecutive_failures });
  if (heartbeat.recovery_alert) warnings.push({ code: 'DISPATCH_HEARTBEAT_RECOVERY' });
  return {
    ok: true,
    request_id: dispatchText(requestId),
    operation_id: `op-dispatch-tick-${sha256(dispatchText(requestId)).slice(0, 32)}`,
    status: 'PLANNED',
    data: {
      dispatch_count: dispatches.length,
      warning_count: warnings.length,
    },
    decisions,
    dispatches,
    warnings,
    heartbeat,
    write_plan: [
      heartbeat.history_row,
      ...decisions.filter((decision) => decision.history_row).map((decision) => decision.history_row),
    ].map((row) => ({ sheet: 'DISPATCH_HISTORY', action: 'APPEND', row })),
  };
}


const gateway = $('Call Config Gateway').first()?.json ?? {};
const trigger = $('Create Dispatcher Envelope').first()?.json?.envelope ?? {};
const historyRows = $items('Read DISPATCH_HISTORY')
  .map((item) => item.json)
  .filter((row) => row && Object.keys(row).length > 0);
const tables = gateway.response?.data?.dispatcher_tables
  ?? gateway.data?.dispatcher_tables
  ?? trigger.payload?.dispatcher_tables
  ?? {};
const scheduleRows = tables.CONFIG_LICH ?? [];
const branchRows = tables.CONFIG_BRANCH ?? [];
const globalRows = tables.CONFIG_GLOBAL ?? [];
const thresholdRow = globalRows.find((row) => String(row.config_key ?? '').trim() === 'DISPATCH_HEARTBEAT_FAILURE_THRESHOLD');
const failureThreshold = Number(thresholdRow?.config_value);
const defaultTimezone = globalRows.find((row) => String(row.config_key ?? '').trim() === 'DEFAULT_TIMEZONE')?.config_value ?? '';
const configVersion = gateway.response?.config_version ?? gateway.config_version ?? trigger.config_version ?? '';
const tickAt = trigger.payload?.tick_at ?? new Date().toISOString();

if (gateway.ok === false) {
  return [{ json: {
    ok: false,
    status: 'ERROR',
    error_code: gateway.response?.error_code ?? 'CONFIG_GATEWAY_UNAVAILABLE',
    request_id: trigger.request_id ?? '',
    operation_id: trigger.operation_id ?? '',
    dispatches: [],
    warnings: [],
  } }];
}
if (!Array.isArray(scheduleRows) || !Array.isArray(branchRows) || !Number.isSafeInteger(failureThreshold) || failureThreshold < 1) {
  return [{ json: {
    ok: false,
    status: 'ERROR',
    error_code: 'DISPATCHER_CONFIG_SNAPSHOT_INCOMPLETE',
    message_safe: 'Dispatcher configuration snapshot does not expose CONFIG_LICH, CONFIG_BRANCH and heartbeat threshold',
    request_id: trigger.request_id ?? '',
    operation_id: trigger.operation_id ?? '',
    dispatches: [],
    warnings: [],
  } }];
}

const plan = buildDispatchPlan({
  scheduleRows,
  branchRows,
  historyRows,
  defaultTimezone,
  now: tickAt,
  requestId: trigger.request_id,
  configVersion,
  heartbeatSuccess: gateway.ok !== false,
  heartbeatFailureThreshold: failureThreshold,
});
return [{ json: plan }];
